(67, 1, '2025-11-10 21:29:12', '2025-11-10 18:29:12', '', 'image-1', '', 'inherit', 'open', 'closed', '', 'image-1', '', '', '2025-11-10 21:29:12', '2025-11-10 18:29:12', '', 65, 'https://neven.ru/wp-content/uploads/2025/11/image-1.png', 0, 'attachment', 'image/png', 0);
